async () => {
  const results = {};

  // capture protected state
  const baseRes = await fetch('/api/documents/incident-alpha');
  const baseData = await baseRes.json();
  const protectedRevision = baseData.revision;
  const protectedContent = baseData.content;
  const protectedLen = protectedContent.length;

  const revListRes = await fetch('/api/documents/incident-alpha/revisions');
  const revListData = await revListRes.json();
  const protectedRevList = revListData.revisions.map(r => r.revision);

  async function probe(name, url, bodyObj) {
    let res, body;
    try {
      res = await fetch(url, {
        method: 'PUT',
        headers: { 'content-type': 'application/json' },
        body: bodyObj === undefined ? undefined : JSON.stringify(bodyObj)
      });
      try { body = await res.json(); } catch(e) { body = await res.text(); }
    } catch(e) {
      results[name] = { error: String(e) };
      return;
    }
    results[name] = { status: res.status, body: typeof body === 'string' ? body.slice(0,200) : body };
  }

  // 1. unknown URL document id
  await probe('unknown_doc_id', '/api/documents/does-not-exist-xyz', { id: 'does-not-exist-xyz', baseRevision: 1, content: 'x' });

  // 2. URL/body document-id mismatch
  await probe('id_mismatch', '/api/documents/incident-alpha', { id: 'some-other-id', baseRevision: protectedRevision, content: protectedContent + ' MISMATCH-ATTEMPT' });

  // 3. missing base revision
  await probe('missing_base_revision', '/api/documents/incident-alpha', { id: 'incident-alpha', content: protectedContent + ' MISSING-BASE-REV' });

  // 4. string base revision
  await probe('string_base_revision', '/api/documents/incident-alpha', { id: 'incident-alpha', baseRevision: String(protectedRevision), content: protectedContent + ' STRING-BASE-REV' });

  // 5. fractional base revision
  await probe('fractional_base_revision', '/api/documents/incident-alpha', { id: 'incident-alpha', baseRevision: protectedRevision + 0.5, content: protectedContent + ' FRACTIONAL-BASE-REV' });

  // 6. missing content
  await probe('missing_content', '/api/documents/incident-alpha', { id: 'incident-alpha', baseRevision: protectedRevision });

  // 7. null content
  await probe('null_content', '/api/documents/incident-alpha', { id: 'incident-alpha', baseRevision: protectedRevision, content: null });

  // re-read after this batch
  const afterRes = await fetch('/api/documents/incident-alpha');
  const afterData = await afterRes.json();
  const afterRevListRes = await fetch('/api/documents/incident-alpha/revisions');
  const afterRevListData = await afterRevListRes.json();

  return {
    protectedRevision, protectedLen, protectedRevList,
    results,
    afterRevision: afterData.revision,
    afterLen: afterData.content.length,
    afterTail: afterData.content.slice(-60),
    afterRevList: afterRevListData.revisions.map(r => r.revision)
  };
}

